parentheses() {
  let last = this.current.last;
  let unbalanced = 1;
  this.position++;
  if (last && last.type === types.PSEUDO) {
    const selector = new Selector({
      source: { start: tokenStart(this.tokens[this.position]) },
      sourceIndex: this.tokens[this.position][TOKEN.START_POS],
    });
