      while (this.position < this.tokens.length && unbalanced) {
        if (this.currToken[TOKEN.TYPE] === tokens.openParenthesis) {
          unbalanced++;
        }
        if (this.currToken[TOKEN.TYPE] === tokens.closeParenthesis) {
          unbalanced--;
