              spaceBefore = "";
            }
            if (commentBefore) {
              ensureObject(node, "raws", "spaces", "attribute");
              node.raws.spaces.attribute.before = commentBefore;
              commentBefore = "";
            }
            node.namespace = (node.namespace || "") + content;
            const rawValue = getProp(node, "raws", "namespace") || null;
