  }

  /**
   *
   * @param {*} nodes
   */
  convertWhitespaceNodesToSpace(nodes, requiredSpace = false) {
    let space = "";
    let rawSpace = "";
    nodes.forEach((n) => {
      let spaceBefore = this.lossySpace(n.spaces.before, requiredSpace);
      let rawSpaceBefore = this.lossySpace(n.rawSpaceBefore, requiredSpace);
      space +=
        spaceBefore + this.lossySpace(n.spaces.after, requiredSpace && spaceBefore.length === 0);
      rawSpace +=
        spaceBefore +
        n.value +
        this.lossySpace(n.rawSpaceAfter, requiredSpace && rawSpaceBefore.length === 0);
    });
    if (rawSpace === space) {
      rawSpace = undefined;
    }
    let result = { space, rawSpace };
    return result;
  }

  isNamedCombinator(position = this.position) {
    return (
      this.tokens[position + 0] &&
      this.tokens[position + 0][TOKEN.TYPE] === tokens.slash &&
      this.tokens[position + 1] &&
      this.tokens[position + 1][TOKEN.TYPE] === tokens.word &&
      this.tokens[position + 2] &&
      this.tokens[position + 2][TOKEN.TYPE] === tokens.slash
    );
  }
  namedCombinator() {
    if (this.isNamedCombinator()) {
      let nameRaw = this.content(this.tokens[this.position + 1]);
      let name = unesc(nameRaw).toLowerCase();
      let raws = {};
      if (name !== nameRaw) {
        raws.value = `/${nameRaw}/`;
      }
      let node = new Combinator({
        value: `/${name}/`,
        source: getSource(
          this.currToken[TOKEN.START_LINE],
          this.currToken[TOKEN.START_COL],
          this.tokens[this.position + 2][TOKEN.END_LINE],
          this.tokens[this.position + 2][TOKEN.END_COL],
        ),
        sourceIndex: this.currToken[TOKEN.START_POS],
        raws,
      });
